package com.sih.hr.service;
import com.sih.hr.dto.HrDtos.*; import com.sih.hr.entity.*; import com.sih.hr.repository.*; import com.sih.shared.tenant.TenantContext; import java.time.*; import java.util.*; import org.springframework.http.HttpStatus; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import org.springframework.web.server.ResponseStatusException;
@Service @Transactional public class HrWorkflowService { private final StaffMemberRepository staff; private final CredentialRepository credentials; private final ShiftAssignmentRepository shifts; public HrWorkflowService(StaffMemberRepository staff,CredentialRepository credentials,ShiftAssignmentRepository shifts){this.staff=staff;this.credentials=credentials;this.shifts=shifts;} private String tenant(){return TenantContext.requireCurrentTenant();} private StaffMember staff(Long id){return staff.findByIdAndTenantId(id,tenant()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Collaborateur introuvable"));} private Credential credential(Long id){return credentials.findByIdAndTenantId(id,tenant()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Accréditation introuvable"));} private ShiftAssignment shift(Long id){return shifts.findByIdAndTenantId(id,tenant()).orElseThrow(()->new ResponseStatusException(HttpStatus.NOT_FOUND,"Planning introuvable"));}
 public List<StaffResponse> listStaff(){return staff.findByTenantIdOrderByLastNameAsc(tenant()).stream().map(this::toStaff).toList();} public StaffResponse createStaff(CreateStaffRequest r){StaffMember s=new StaffMember();s.setEmployeeNumber(r.employeeNumber());s.setFirstName(r.firstName());s.setLastName(r.lastName());s.setDepartment(r.department());s.setPosition(r.position());s.setClinicalStaff(r.clinicalStaff());s.setEmail(r.email());if(r.hiredOn()!=null)s.setHiredOn(r.hiredOn());return toStaff(staff.save(s));}
 public List<CredentialResponse> listCredentials(){return credentials.findByTenantIdOrderByExpiresOnAsc(tenant()).stream().map(this::toCredential).toList();} public CredentialResponse createCredential(CreateCredentialRequest r){if(!r.expiresOn().isAfter(r.issuedOn()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"La date d’expiration doit être postérieure à la date de délivrance");Credential c=new Credential();c.setStaff(staff(r.staffId()));c.setType(r.type());c.setCredentialNumber(r.credentialNumber());c.setIssuedOn(r.issuedOn());c.setExpiresOn(r.expiresOn());return toCredential(credentials.save(c));} public CredentialResponse renewCredential(Long id,RenewCredentialRequest r){Credential c=credential(id);if(!r.expiresOn().isAfter(LocalDate.now()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"Le renouvellement doit être futur");c.setExpiresOn(r.expiresOn());return toCredential(c);}
 public List<ShiftResponse> listShifts(){return shifts.findByTenantIdOrderByStartsAtAsc(tenant()).stream().map(this::toShift).toList();} public ShiftResponse createShift(CreateShiftRequest r){if(!r.endsAt().isAfter(r.startsAt()))throw new ResponseStatusException(HttpStatus.UNPROCESSABLE_ENTITY,"La fin de garde doit être postérieure au début");StaffMember s=staff(r.staffId());if(!"ACTIVE".equals(s.getEmploymentStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Collaborateur inactif");if(s.isClinicalStaff()&&credentials.existsByStaffIdAndTenantIdAndExpiresOnBefore(s.getId(),tenant(),LocalDate.now()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Accréditation clinique expirée");if(shifts.existsByStaffIdAndTenantIdAndStartsAtLessThanAndEndsAtGreaterThan(s.getId(),tenant(),r.endsAt(),r.startsAt()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Chevauchement de garde détecté");ShiftAssignment a=new ShiftAssignment();a.setStaff(s);a.setUnitName(r.unitName());a.setShiftType(r.shiftType());a.setStartsAt(r.startsAt());a.setEndsAt(r.endsAt());a.setNotes(r.notes());return toShift(shifts.save(a));} public ShiftResponse publishShift(Long id){ShiftAssignment a=shift(id);if(!"DRAFT".equals(a.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Seule une garde brouillon peut être publiée");a.setStatus("PUBLISHED");return toShift(a);} public ShiftResponse cancelShift(Long id){ShiftAssignment a=shift(id);if("CANCELLED".equals(a.getStatus()))throw new ResponseStatusException(HttpStatus.CONFLICT,"Garde déjà annulée");a.setStatus("CANCELLED");return toShift(a);}
 private StaffResponse toStaff(StaffMember s){return new StaffResponse(s.getId(),s.getEmployeeNumber(),s.getFirstName(),s.getLastName(),s.getDepartment(),s.getPosition(),s.getEmploymentStatus(),s.isClinicalStaff(),s.getEmail(),s.getHiredOn());} private CredentialResponse toCredential(Credential c){return new CredentialResponse(c.getId(),c.getStaff().getId(),c.getStaff().getFirstName()+" "+c.getStaff().getLastName(),c.getType(),c.getCredentialNumber(),c.getIssuedOn(),c.getExpiresOn(),c.getExpiresOn().isBefore(LocalDate.now()));} private ShiftResponse toShift(ShiftAssignment a){return new ShiftResponse(a.getId(),a.getStaff().getId(),a.getStaff().getFirstName()+" "+a.getStaff().getLastName(),a.getUnitName(),a.getShiftType(),a.getStartsAt(),a.getEndsAt(),a.getStatus(),a.getNotes());}
}
